// lib/borough-stats.ts is generated by scripts/borough-stats.py from the GOV.UK EPC register. These checks
// catch a bad regeneration (a missing borough, a broken sum, personal data leaking in) before it reaches a page.
const test = require('node:test')
const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')
const { boroughStats } = require('../lib/borough-stats.ts')
const { boroughMeta } = require('../lib/boroughs.ts')
const { areaBands } = require('../lib/floor-area.ts')

const all = [...Object.values(boroughStats.boroughs), boroughStats.london, boroughStats.stratford]
const sum = (xs) => xs.reduce((a, n) => a + n, 0)
const near100 = (pcts, label) => {
  const total = sum(Object.values(pcts))
  assert.ok(Math.abs(total - 100) <= 0.3, `${label}: shares add up to ${total}`)
}

// Pinned to one GOV.UK file. When the monthly refresh brings a new file, check the new total is plausible
// and update both values (runbook at the top of scripts/borough-stats.py).
const PINNED = { fileUpdated: '2026-10-13', certificates: 879704 }

test('all 33 London local authorities, and every area page has figures', () => {
  const slugs = Object.keys(boroughStats.boroughs)
  assert.equal(slugs.length, 33)
  for (const slug of slugs) assert.ok(boroughMeta[slug], `${slug} has no area page`)
  for (const [slug, meta] of Object.entries(boroughMeta)) {
    if (meta.kind === 'neighbourhood') assert.equal(boroughStats.stratford.slug, slug, `${slug} has no figures`)
    else assert.ok(boroughStats.boroughs[slug], `${slug} has no figures`)
  }
})

test('the London total matches the pinned GOV.UK file', () => {
  if (boroughStats.source.fileUpdated === PINNED.fileUpdated) {
    assert.equal(boroughStats.london.certificates, PINNED.certificates)
  } else {
    assert.fail(`new GOV.UK file ${boroughStats.source.fileUpdated}: check the total (${boroughStats.london.certificates}) and update PINNED`)
  }
})

test('the London row is the sum of the 33 boroughs', () => {
  const bs = Object.values(boroughStats.boroughs)
  const L = boroughStats.london
  assert.equal(sum(bs.map((b) => b.certificates)), L.certificates)
  for (const g of ['AtoC', 'D', 'E', 'FtoG']) assert.equal(sum(bs.map((b) => b.ratings.counts[g])), L.ratings.counts[g], g)
  assert.equal(sum(bs.map((b) => b.privateRented.n)), L.privateRented.n)
  assert.equal(sum(bs.map((b) => b.privateRented.nFtoG)), L.privateRented.nFtoG)
  for (const year of Object.keys(L.byYear)) assert.equal(sum(bs.map((b) => b.byYear[year]?.n ?? 0)), L.byYear[year].n, year)
  for (let i = 0; i < L.sizeBands.length; i++) assert.equal(sum(bs.map((b) => b.sizeBands[i].n)), L.sizeBands[i].n, L.sizeBands[i].id)
  // Each borough's yearly average is rounded, so the sum may drift by up to half a certificate per borough.
  assert.ok(Math.abs(sum(bs.map((b) => b.marketPerYear)) - L.marketPerYear) <= bs.length / 2)
})

test('shares add up to 100 and sit in range', () => {
  for (const a of all) {
    near100(a.ratings.pct, `${a.name} ratings`)
    for (const [y, m] of Object.entries(a.byYear)) near100(m.pct, `${a.name} ${y}`)
    near100(Object.fromEntries(a.sizeBands.map((s) => [s.id, s.pct])), `${a.name} sizes`)
    for (const key of ['age', 'walls', 'heating']) near100(a[key].pct, `${a.name} ${key}`)
    for (const v of [a.privateRented.pctBelowC, a.privateRented.pctFtoG, a.pctFlats, a.pctLettings, a.pctSales,
      a.potential.pctAtoC, a.potential.pctBelowCCouldReachC]) assert.ok(v >= 0 && v <= 100, `${a.name}: ${v}`)
    assert.ok(a.ratings.n <= a.certificates && a.ratings.n >= a.certificates * 0.99, a.name)
  }
})

test('size bands are the live pricing bands, in order', () => {
  for (const a of all) {
    assert.deepEqual(a.sizeBands.map((s) => s.id), [...areaBands], a.name)
    assert.ok(areaBands.includes(a.commonestBand.id), a.name)
    assert.equal(a.commonestBand.pct, Math.max(...a.sizeBands.map((s) => s.pct)), a.name)
  }
})

test('postcode districts are outward codes over the threshold, and the rest is folded', () => {
  const min = boroughStats.thresholds.districtMin
  for (const a of [...Object.values(boroughStats.boroughs), boroughStats.stratford]) {
    for (const d of a.districts) {
      assert.match(d.district, /^[A-Z]{1,2}[0-9][A-Z0-9]?$/, `${a.name}: ${d.district}`)
      assert.ok(d.n >= min, `${a.name} ${d.district}: ${d.n} is under ${min}`)
    }
    assert.equal(sum(a.districts.map((d) => d.n)) + a.otherDistricts.n, a.certificates, a.name)
  }
  assert.deepEqual(boroughStats.london.districts, [])
})

test('Stratford is its postcode districts, not a council', () => {
  const s = boroughStats.stratford
  assert.equal(boroughStats.boroughs.stratford, undefined)
  assert.equal(s.code, null)
  assert.deepEqual(s.definedBy, ['E15', 'E20'])
  for (const d of s.districts) assert.ok(s.definedBy.includes(d.district), d.district)
  assert.equal(sum(Object.values(s.localAuthorities)), s.certificates)
})

test('no personal data: no full postcode, address, UPRN or certificate number in the generated file', () => {
  const text = fs.readFileSync(path.join(__dirname, '..', 'lib', 'borough-stats.ts'), 'utf8')
  assert.doesNotMatch(text, /\b[A-Z]{1,2}[0-9][A-Z0-9]? ?[0-9][A-Z]{2}\b/, 'full postcode')
  assert.doesNotMatch(text, /uprn|address/i, 'UPRN or address field')
  assert.doesNotMatch(text, /\b\d{4}-\d{4}-\d{4}-\d{4}-\d{4}\b/, 'certificate number')
})

test('every figure carries its source and dates', () => {
  const src = boroughStats.source
  assert.equal(src.licence, 'Open Government Licence v3.0')
  assert.ok(src.url.startsWith('https://'))
  for (const d of [src.fileUpdated, src.from, src.to, src.generated]) assert.match(d, /^\d{4}-\d{2}-\d{2}$/)
  assert.ok(src.from <= src.to && src.to <= src.fileUpdated)
  assert.ok(src.caveats.length >= 4)
})
